<?php require_once __DIR__.'/includes/bootstrap.php';$token=$_GET['token']??'';$s=$conn->prepare('SELECT id FROM users WHERE verification_token=? AND email_verified=0 AND verification_expires>NOW() LIMIT 1');$s->bind_param('s',$token);$s->execute();$u=$s->get_result()->fetch_assoc();if($u){$id=(int)$u['id'];$s=$conn->prepare('UPDATE users SET email_verified=1,verification_token=NULL,verification_expires=NULL WHERE id=?');$s->bind_param('i',$id);$s->execute();log_activity($conn,$id,'email_verified','Verification successful');flash('success','Email verified. Please log in.');}else flash('error','Invalid, expired, or already-used verification link.');redirect('login.php');?>